# Substrate §3.1 — Privacy / Redaction Gate (stub).
# All logic at top level — no nested function defs. See note in
# proactive-substrate-stub.json's Privacy transform.
import re
env = dict(input) if isinstance(input, dict) else {"raw": input}

EMAIL = re.compile(r"\b[\w.+-]+@[\w-]+\.[\w.-]+\b")
SSN   = re.compile(r"\b\d{3}-\d{2}-\d{4}\b")
CARD  = re.compile(r"\b\d{13,19}\b")

_targets = []
for key in ("payload", "raw", "body", "message", "observation"):
    if key in env:
        _targets.append((env, key))

while _targets:
    parent, key = _targets.pop()
    val = parent[key]
    if isinstance(val, str):
        v = EMAIL.sub("[email]", val)
        v = SSN.sub("[ssn]", v)
        v = CARD.sub("[card]", v)
        parent[key] = v
    elif isinstance(val, dict):
        for k in list(val.keys()):
            _targets.append((val, k))
    elif isinstance(val, list):
        for i in range(len(val)):
            _targets.append((val, i))

env.setdefault("provenance", []).append({"stage": "privacy", "redacted": True})
output = env

# Substrate §3.1 — Adversarial-Input Filter (stub).
env = dict(input) if isinstance(input, dict) else {"raw": input}

payload = None
for key in ("payload", "raw", "body", "message"):
    if key in env:
        payload = env.pop(key)
        break
env["untrusted_content"] = payload
env.setdefault("provenance", []).append({"stage": "adversarial", "wrapped": True})
output = env

# Substrate §3.4 — Capability Registry (stub).
# Lazy-seeds a small built-in catalog. If the envelope carries an
# `intent.capability` field, look up the registered scopes and fold
# them into env["scopes"]. Real impl: tools register at runtime via
# a Manifest with versioning.
env  = dict(input) if isinstance(input, dict) else {"raw": input}
caps = variables.setdefault("capabilities", {})

if not caps:
    caps["core.notify"] = {
        "name":          "core.notify",
        "purpose":       "Surface a UI notification to the user",
        "scopes":        ["read-only"],
        "latency_tier":  "interactive",
        "cost_estimate": 0.0,
    }
    caps["core.send_email"] = {
        "name":          "core.send_email",
        "purpose":       "Send an outbound email",
        "scopes":        ["write", "external-network", "affects-third-party"],
        "latency_tier":  "responsive",
        "cost_estimate": 0.001,
    }
    caps["core.transfer_funds"] = {
        "name":          "core.transfer_funds",
        "purpose":       "Initiate a money transfer",
        "scopes":        ["spends-money", "write", "affects-third-party"],
        "latency_tier":  "responsive",
        "cost_estimate": 0.5,
    }

intent   = env.get("intent") or {}
cap_name = intent.get("capability")
if cap_name and cap_name in caps:
    cap = caps[cap_name]
    env["resolved_capability"] = {
        "name":         cap_name,
        "scopes":       cap["scopes"],
        "latency_tier": cap["latency_tier"],
    }
    env["scopes"] = sorted(set(list(env.get("scopes", [])) + list(cap["scopes"])))
    env.setdefault("provenance", []).append({"stage": "capability_registry", "resolved": cap_name})
else:
    env.setdefault("provenance", []).append({"stage": "capability_registry", "resolved": None})
output = env

# Substrate §3.5 — Governor (stub). For pure Sensory observations this is
# a near no-op (read-only → allow), but keeping it on-path means anything
# the Sensory stage later promotes (e.g. an action proposal) is gated
# without changing the topology.
# Explicit loop instead of any(...) genexp — see substrate-stub note.
env    = dict(input) if isinstance(input, dict) else {"raw": input}
scopes = list(env.get("scopes", ["read-only"]))
conf   = float(env.get("confidence", 1.0))

HIGH_STAKE = {"spends-money", "impersonates-user", "affects-third-party"}
WRITE      = {"write"}

has_high  = False
has_write = False
for s in scopes:
    if s in HIGH_STAKE: has_high  = True
    if s in WRITE:      has_write = True

if has_high:
    decision, reason = "consent_required", "high-stake scope present"
elif has_write and conf < 0.85:
    decision, reason = "consent_required", "write at low confidence"
else:
    decision, reason = "allow", "low-class action"

env["governor_verdict"] = {
    "decision":   decision,
    "reason":     reason,
    "scopes":     scopes,
    "confidence": conf,
}
output = env
